package com.atlasiq.security;
import com.atlasiq.persistence.*;import com.atlasiq.qir.*;import jakarta.enterprise.context.ApplicationScoped;import java.util.*;
@ApplicationScoped public class SecurityBlastRadiusService {private final AnalysisStore store;public SecurityBlastRadiusService(AnalysisStore s){store=s;}public Result analyze(String id,String resource,int depth){QirModel m=store.find(id).orElseThrow().model();Set<String> seen=new LinkedHashSet<>(List.of(resource)),front=new LinkedHashSet<>(seen);List<QirEdge> paths=new ArrayList<>();for(int d=0;d<Math.max(1,Math.min(depth,6));d++){Set<String> next=new LinkedHashSet<>();for(QirEdge e:m.edges())if(Set.of("depends_on","calls","contains","deployed_as","observed_as","owned_by","reads_secret","mounts_secret").contains(e.relationship())&&front.contains(e.to())&&!seen.contains(e.from())){next.add(e.from());paths.add(e);}seen.addAll(next);front=next;}return new Result(resource,m.nodes().stream().filter(n->seen.contains(n.id())).toList(),List.copyOf(paths));}public record Result(String source,List<QirNode> affected,List<QirEdge> paths){}
}